import { required, decimal } from 'vuelidate/lib/validators'

const setConfig = (state, methods) => ({
  state,
  methods,
  dialogData: {
    opened: state.opened,
    icon: 'mdi-cash-register',
    title: 'starterLayout.openRegister.amountDialogTitle',
    persistent: true,
    titleBackground: '#white',
    titleColor: 'textPrimary',
    buttonTextColor: {
      cancel: 'white',
      accept: 'white',
    },
    buttonColor: {
      cancel: 'accent',
      accept: 'primary',
    },
    messages: ['starterLayout.openRegister.amountDialog'],
    height: 300,
    maxWidth: 500,
    id: 'open-register-amount-form',
    onClickCancel: () => methods.closeDialog(),
    onClickAccept: () => methods.openRegister(),
  },
  fields: [
    {
      id: 'amount',
      type: 'input',
      valueType: 'number',
      label: 'shared.amount',
      errorMessage: 'starterLayout.openRegister.errorAmount',
      color: 'primaryColor',
      required: true,
      autofocus: true,
      validators: { required, decimal },
    },
  ],
  id: 'open-register-amount-form',
})

export default setConfig
