import { required } from 'vuelidate/lib/validators'

const setConfig = (state, methods) => ({
  state,
  methods,
  fields: [
    {
      id: 'user',
      type: 'select',
      items: state.users,
      label: 'mainLayout.user.user',
      color: 'primary',
      default: 0,
      validators: { required },
      errorMessage: 'starterLayout.openRegister.errorSelect',
    },
    {
      id: 'password',
      type: 'password',
      autofocus: true,
      validators: { required },
    },
    {
      id: 'text',
      type: 'textLink',
      onClick: methods.onClickRememberPassword,
      class: 'text-center mb-3',
      textType: 'text-subtitle-2',
      color: 'primary',
      intl: true,
      value: 'starterLayout.login.passwordRemember',
    },
  ],
  id: 'open-register-form',
  onSubmit: () => methods.submit(),
})

export default setConfig
