<template>
  <div>
    <OpenRegisterForm @openDialog="openAmountDialog = true" />
    <AmountDialog
      v-if="openAmountDialog"
      :opened="openAmountDialog"
      @closeDialog="openAmountDialog = false"
    />
  </div>
</template>

<script>
import OpenRegisterForm from '@/components/AuthViews/OpenRegisterView/OpenRegisterForm'
import AmountDialog from '@/components/AuthViews/OpenRegisterView/AmountDialog'

export default {
  name: 'OpenRegisterView',
  components: { OpenRegisterForm, AmountDialog },
  data() {
    return {
      openAmountDialog: false,
    }
  },
}
</script>
