<template>
  <DialogCard :config="componentConfig.dialogData">
    <Form :config="componentConfig" />
  </DialogCard>
</template>

<script>
import { isNil } from 'ramda'
import { mapState, mapActions } from 'vuex'

import OPEN_REGISTER_EVENTS from '@/config/events/openRegister'

import { cleanObjectObserver } from '@/tools/data'
import { captureException } from '@/tools/exceptions'
import { formatNumberToDb } from '@/tools/numbersFormat'

import notificationsService from '@/services/renderer/notifications'
import rendererEventsService from '@/services/renderer/rendererEvents'

import appActions from '@/store/app/actions.types'
import usersViewActions from '@/store/usersView/actions.types'

import setConfig from '@/components/AuthViews/OpenRegisterView/AmountDialog/config'
import DialogCard from '@/components/shared/DialogCard'
import Form from '@/components/shared/Form'

export default {
  name: 'AmountDialog',
  components: { DialogCard, Form },
  props: {
    opened: {
      type: Boolean,
      default: false,
    },
  },
  data() {
    return {
      inputs: {},
      validators: { inputs: {} },
      openingRegister: false,
    }
  },
  computed: {
    ...mapState('usersView', ['estimatedCash', 'selectedUser']),
    isOpened() {
      return this.opened
    },
    componentConfig() {
      return setConfig(
        {
          opened: this.isOpened,
          inputs: this.inputs,
          v: this.$v.inputs,
        },
        {
          closeDialog: this.closeDialog,
          openRegister: this.openRegister,
        }
      )
    },
  },
  methods: {
    ...mapActions('app', [appActions.setIsStoreOpen]),
    ...mapActions('usersView', [usersViewActions.setUserEstimatedCash]),
    setProperties: function() {
      this.componentConfig.fields.forEach(field => {
        this.$set(this.inputs, field.id, '')
        if (field.validators)
          this.$set(this.validators.inputs, field.id, {
            ...cleanObjectObserver(field.validators),
          })
      })
    },
    openRegister() {
      if (this.openingRegister === true) return
      if (this.$v.inputs.$invalid) {
        Object.keys(this.inputs).forEach(key => this.$v.inputs[key].$touch())
        return
      }
      this.$track({
        type: 'interaction',
        action: 'click',
        category: 'OpenStore',
        screen: 'AmountDialog',
        name: 'Submit',
      })
      this.openingRegister = true
      const estimatedCash = this.getNewEstimatedCash()
      rendererEventsService.send(OPEN_REGISTER_EVENTS.channel, {
        event: OPEN_REGISTER_EVENTS.events.openRegister.name,
        data: {
          userId: this.selectedUser.id,
          estimatedCash: formatNumberToDb(estimatedCash),
          amount: formatNumberToDb(this.inputs.amount),
        },
      })
    },
    closeDialog() {
      Object.keys(this.inputs).forEach(key => this.$v.inputs[key].$reset())
      Object.keys(this.inputs).forEach(key => (this.inputs[key] = ''))
      this.$emit('closeDialog')
    },
    getNewEstimatedCash() {
      const currentEstimatedCash = isNil(this.estimatedCash)
        ? 0
        : this.estimatedCash
      return currentEstimatedCash + parseFloat(this.inputs.amount)
    },
  },
  validations() {
    return this.validators
  },
  created() {
    rendererEventsService.subscribe(
      OPEN_REGISTER_EVENTS.replyChannel,
      (event, payload) => {
        const replies = {
          [OPEN_REGISTER_EVENTS.events.openRegister.replies.error]: () => {
            notificationsService.showError(
              payload.data.message,
              this.$vuetify.lang
            )
            this.$track({
              type: 'system',
              action: 'error',
              category: 'OpenStore',
              screen: 'AmountDialog',
              name: 'Error opening cash register',
            })
            this.openingRegister = false
          },
          [OPEN_REGISTER_EVENTS.events.openRegister.replies.success]: () => {
            this.$track({
              type: 'system',
              action: 'response',
              category: 'OpenStore',
              screen: 'AmountDialog',
              name: `Go to ${
                this.selectedUser.hasSales ? 'Sales' : 'Help center'
              }`,
            })
            const estimatedCash = this.getNewEstimatedCash()
            this[usersViewActions.setUserEstimatedCash](estimatedCash)
            this[appActions.setIsStoreOpen]()
            this.openingRegister = false
            const path = this.selectedUser.hasSales
              ? '/app/sales'
              : '/app/helpCenter'
            this.$router.push({ path }).catch(error => captureException(error))
            notificationsService.showSuccess(
              'notification.users.openRegisterSuccess',
              this.$vuetify.lang
            )
          },
        }
        replies[payload.event]()
      }
    )
  },
  mounted: async function() {
    this.setProperties()
  },
  beforeDestroy() {
    rendererEventsService.removeAllListeners(OPEN_REGISTER_EVENTS.replyChannel)
  },
}
</script>
