<template>
  <v-card class="pa-6 form-card">
    <div class="primary form-top-bar" />
    <v-card-title class="justify-center">
      <FormattedText
        type="text-h6"
        intl
        value="starterLayout.openRegister.title"
      />
    </v-card-title>
    <v-card-subtitle class="text-center">
      <FormattedText
        type="text-subtitle-2"
        intl
        value="starterLayout.openRegister.subtitle"
        color="primary"
      />
    </v-card-subtitle>

    <v-list-item-avatar size="65" class="mb-0">
      <img :src="shopImg" />
    </v-list-item-avatar>
    <FormattedText
      type="text-h5"
      className="font-weight-bold"
      color="textPrimary"
      :value="storeName === '' ? 'shared.myStore' : storeName"
      :intl="storeName === ''"
    />

    <v-card-text class="text--primary">
      <Form :config="formConfig" />
      <div class="text-center loader-errors-space mt-1">
        <transition appear name="fade" v-if="error">
          <v-alert text type="error" class="my-0">
            <FormattedText type="text-caption" intl :value="error" />
          </v-alert>
        </transition>
      </div>
    </v-card-text>

    <v-card-actions>
      <CustomButton
        className="submit-button"
        block
        large
        rounded
        :disabled="$v.inputs.$invalid"
        type="submit"
        :form="formConfig.id"
        @click="formConfig.onSubmit"
        text="starterLayout.openRegister.submit"
        textType="text-subtitle-2"
        textClass="text-capitalize"
        intl
        v-track:click="{
          category: 'OpenStore',
          screen: 'OpenLoggedStore',
          name: 'Open cash register',
        }"
      />
    </v-card-actions>
  </v-card>
</template>

<script>
import { mapState, mapActions } from 'vuex'

import USERS_EVENTS from '@/config/events/users'

import { cleanObjectObserver } from '@/tools/data'

import rendererEventsService from '@/services/renderer/rendererEvents'

import usersViewActions from '@/store/usersView/actions.types'
import appActions from '@/store/app/actions.types'

import Form from '@/components/shared/Form'
import FormattedText from '@/components/shared/FormattedText'
import CustomButton from '@/components/shared/CustomButton'

import setConfig from '@/components/AuthViews/OpenRegisterView/OpenRegisterForm/config'

export default {
  name: 'OpenRegisterForm',
  components: { Form, FormattedText, CustomButton },
  data() {
    return {
      inputs: {},
      validators: { inputs: {} },
      error: null,
    }
  },
  computed: {
    ...mapState('account', {
      store: state => state.data.storeName,
      storeImage: state => state.data.storeImage,
      ownerName: state => state.data.name,
      account: state => state.data.account,
    }),
    ...mapState('users', ['users']),
    shopImg() {
      if (this.storeImage.length === 0)
        return require('@/assets/default_shop.png')
      return `data:image/jpg;base64,${this.storeImage}`
    },
    storeName() {
      return this.store ? this.store : ''
    },
    formConfig: function() {
      return setConfig(
        {
          inputs: this.inputs,
          v: this.$v.inputs,
          users: this.allUsers,
        },
        {
          submit: this.submit,
          onClickRememberPassword: this.openRememberPassword,
        }
      )
    },
    allUsers() {
      const allUsers = this.users
      return allUsers
        .filter(user => user.deleted === 0)
        .map(user => {
          return {
            id: user._id,
            text:
              user._id == 1 && this.ownerName.length > 2
                ? this.ownerName.split(' ')[0]
                : user.name,
            password: user.password,
          }
        })
    },
  },
  validations() {
    return this.validators
  },
  methods: {
    ...mapActions('usersView', [usersViewActions.setSelectedUser]),
    ...mapActions('app', [appActions.setRememberPasswordDialogStatus]),
    getTranslatedText: function(translateString) {
      return this.$vuetify.lang.t(`$vuetify.${translateString}`)
    },
    setProperties: function() {
      this.formConfig.fields.forEach(field => {
        'default' in field
          ? this.$set(this.inputs, field.id, this.allUsers[field.default].id)
          : this.$set(this.inputs, field.id, '')
        if (field.validators)
          this.$set(this.validators.inputs, field.id, {
            ...cleanObjectObserver(field.validators),
          })
      })
    },
    submit: function() {
      const data = Object.create(this.inputs)
      rendererEventsService.send(USERS_EVENTS.channel, {
        event: USERS_EVENTS.events.changeUser.name,
        data: { selectedUserId: data.user, password: data.password },
      })
    },
    openRememberPassword() {
      this[appActions.setRememberPasswordDialogStatus](true)
    },
  },
  created() {
    rendererEventsService.subscribe(
      USERS_EVENTS.replyChannel,
      (event, payload) => {
        const replies = {
          [USERS_EVENTS.events.changeUser.replies.error]: () => {
            this.error = payload.data.message
            if (payload.data.message.includes('incorrectPassword')) return
            this.$track({
              type: 'system',
              action: 'error',
              category: 'OpenStore',
              screen: 'OpenLoggedStore',
              name: 'Error opening store',
            })
          },
          [USERS_EVENTS.events.changeUser.replies.success]: () => {
            this.$emit('openDialog')
            this.error = null
            this[usersViewActions.setSelectedUser](payload.data)
          },
        }
        replies[payload.event]()
      }
    )
  },
  mounted: async function() {
    this.setProperties()
  },
  beforeDestroy() {
    rendererEventsService.removeAllListeners(USERS_EVENTS.replyChannel)
  },
}
</script>

<style lang="scss" scoped>
.form-card {
  border-radius: 8px !important;
  position: relative;
}
.form-top-bar {
  height: 8px;
  width: 100%;
  position: absolute;
  top: 0;
  left: 0;
}
.loader-errors-space {
  height: 60px;
}
.submit-button {
  min-width: 100% !important;
}
</style>
